-- ─── 1. pseo_dimension_catalog ──────────────────────────────────────────
CREATE TABLE IF NOT EXISTS pseo_dimension_catalog (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hostname TEXT NOT NULL REFERENCES registered_domains(hostname) ON UPDATE CASCADE ON DELETE CASCADE,
    dimension_type TEXT NOT NULL,
    slug TEXT NOT NULL,
    display_value TEXT NOT NULL,
    metadata JSONB DEFAULT '{}'::jsonb,
    search_volume_estimate INT DEFAULT 0,
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(hostname, dimension_type, slug)
);

CREATE INDEX IF NOT EXISTS idx_pseo_dim_host_type ON pseo_dimension_catalog(hostname, dimension_type);
CREATE INDEX IF NOT EXISTS idx_pseo_dim_host_active ON pseo_dimension_catalog(hostname, active);

COMMENT ON TABLE pseo_dimension_catalog IS 'Stores seed dimension values (roles, cities, skills, etc.) for deterministic programmatic SEO page generation without storing combinatorial permutations in DB.';

-- ─── 2. pseo_hub_pages ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS pseo_hub_pages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hostname TEXT NOT NULL REFERENCES registered_domains(hostname) ON UPDATE CASCADE ON DELETE CASCADE,
    hub_level INT NOT NULL CHECK (hub_level IN (1, 2)),
    slug TEXT NOT NULL,
    parent_slug TEXT,
    display_title TEXT NOT NULL,
    meta_description TEXT,
    dimension_filter JSONB NOT NULL DEFAULT '{}'::jsonb,
    estimated_children INT DEFAULT 0,
    sitemap_priority NUMERIC(3,2) DEFAULT 0.8,
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(hostname, slug)
);

CREATE INDEX IF NOT EXISTS idx_pseo_hub_host_level ON pseo_hub_pages(hostname, hub_level);
CREATE INDEX IF NOT EXISTS idx_pseo_hub_parent ON pseo_hub_pages(hostname, parent_slug);

COMMENT ON TABLE pseo_hub_pages IS 'Stores macro hubs (Click-1) and micro clusters (Click-2) ensuring 3-click navigation and high sitemap authority for pSEO URL routing.';

-- ─── 3. gsc_telemetry ────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS gsc_telemetry (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hostname TEXT NOT NULL REFERENCES registered_domains(hostname) ON UPDATE CASCADE ON DELETE CASCADE,
    date DATE NOT NULL,
    total_indexed_pages INT DEFAULT 0,
    total_impressions BIGINT DEFAULT 0,
    total_clicks BIGINT DEFAULT 0,
    average_position NUMERIC(6,2),
    crawl_requests_today INT DEFAULT 0,
    pages_submitted_today INT DEFAULT 0,
    indexnow_submissions_today INT DEFAULT 0,
    quota_used_today INT DEFAULT 0,
    top_rising_queries JSONB DEFAULT '[]'::jsonb,
    raw_api_response JSONB DEFAULT '{}'::jsonb,
    recorded_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(hostname, date)
);

CREATE INDEX IF NOT EXISTS idx_gsc_telemetry_host_date ON gsc_telemetry(hostname, date DESC);

COMMENT ON TABLE gsc_telemetry IS 'Daily Google Search Console and IndexNow telemetry per authoritative hostname.';

-- ─── 4. pseo_bot_wave_queue ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS pseo_bot_wave_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hostname TEXT NOT NULL REFERENCES registered_domains(hostname) ON UPDATE CASCADE ON DELETE CASCADE,
    url_path TEXT NOT NULL,
    priority INT DEFAULT 0,
    dimension_combo JSONB NOT NULL DEFAULT '{}'::jsonb,
    discovered_via TEXT DEFAULT 'sitemap',
    injected_to_redis BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_pseo_bot_wave_host_redis_priority ON pseo_bot_wave_queue(hostname, injected_to_redis, priority DESC);

COMMENT ON TABLE pseo_bot_wave_queue IS 'PostgreSQL-backed priority queue of uncrawled pSEO URLs per hostname, acting as persistent overflow for Redis-driven bot crawling waves.';

-- ─── 5. Seed pseo_dimension_catalog ─────────────────────────────────────
ON CONFLICT (hostname, dimension_type, slug) DO UPDATE SET
    display_value = EXCLUDED.display_value,
    metadata = EXCLUDED.metadata,
    search_volume_estimate = EXCLUDED.search_volume_estimate,
    active = EXCLUDED.active;

-- ─── 6. Seed pseo_hub_pages (5 macro hubs per hostname x 22 hostnames = 110 rows) ───
ON CONFLICT (hostname, slug) DO UPDATE SET
    hub_level = EXCLUDED.hub_level,
    parent_slug = EXCLUDED.parent_slug,
    display_title = EXCLUDED.display_title,
    meta_description = EXCLUDED.meta_description,
    dimension_filter = EXCLUDED.dimension_filter,
    estimated_children = EXCLUDED.estimated_children,
    sitemap_priority = EXCLUDED.sitemap_priority,
    active = EXCLUDED.active;
